// =============================================================================
// color.ts — pure color utilities. No DOM, safe on server & client.
// =============================================================================

export interface RGB {
  r: number; // 0..255
  g: number;
  b: number;
}

export interface HSL {
  h: number; // 0..360
  s: number; // 0..100
  l: number; // 0..100
}

const clamp = (n: number, min: number, max: number) =>
  Math.min(max, Math.max(min, n));

const round = (n: number) => Math.round(n);

// ---- A small set of CSS named colors (used by the parser) -------------------
export const NAMED_COLORS: Record<string, string> = {
  black: "#000000", white: "#ffffff", red: "#ff0000", green: "#008000",
  blue: "#0000ff", yellow: "#ffff00", orange: "#ffa500", purple: "#800080",
  gray: "#808080", grey: "#808080", silver: "#c0c0c0", maroon: "#800000",
  olive: "#808000", lime: "#00ff00", aqua: "#00ffff", teal: "#008080",
  navy: "#000080", fuchsia: "#ff00ff", magenta: "#ff00ff", cyan: "#00ffff",
  pink: "#ffc0cb", brown: "#a52a2a", gold: "#ffd700", indigo: "#4b0082",
  violet: "#ee82ee", coral: "#ff7f50", salmon: "#fa8072", crimson: "#dc143c",
  khaki: "#f0e68c", tomato: "#ff6347", turquoise: "#40e0d0", tan: "#d2b48c",
  beige: "#f5f5dc", ivory: "#fffff0", lavender: "#e6e6fa", plum: "#dda0dd",
  orchid: "#da70d6", slategray: "#708090", slategrey: "#708090",
  darkgray: "#a9a9a9", darkgrey: "#a9a9a9", lightgray: "#d3d3d3",
  lightgrey: "#d3d3d3", whitesmoke: "#f5f5f5", gainsboro: "#dcdcdc",
  dimgray: "#696969", dimgrey: "#696969",
};

// =============================================================================
// Hex <-> RGB
// =============================================================================
export function hexToRgb(hex: string): RGB | null {
  let h = hex.trim().replace(/^#/, "");
  if (h.length === 3 || h.length === 4) {
    h = h.split("").map((c) => c + c).join("");
  }
  if (h.length === 6 || h.length === 8) {
    const r = parseInt(h.slice(0, 2), 16);
    const g = parseInt(h.slice(2, 4), 16);
    const b = parseInt(h.slice(4, 6), 16);
    if ([r, g, b].some(Number.isNaN)) return null;
    return { r, g, b };
  }
  return null;
}

export function rgbToHex({ r, g, b }: RGB): string {
  const to = (n: number) => clamp(round(n), 0, 255).toString(16).padStart(2, "0");
  return `#${to(r)}${to(g)}${to(b)}`;
}

// =============================================================================
// RGB <-> HSL
// =============================================================================
export function rgbToHsl({ r, g, b }: RGB): HSL {
  const rn = r / 255, gn = g / 255, bn = b / 255;
  const max = Math.max(rn, gn, bn), min = Math.min(rn, gn, bn);
  const d = max - min;
  let h = 0;
  if (d !== 0) {
    switch (max) {
      case rn: h = ((gn - bn) / d) % 6; break;
      case gn: h = (bn - rn) / d + 2; break;
      default: h = (rn - gn) / d + 4;
    }
    h *= 60;
    if (h < 0) h += 360;
  }
  const l = (max + min) / 2;
  const s = d === 0 ? 0 : d / (1 - Math.abs(2 * l - 1));
  return { h: round(h), s: round(s * 100), l: round(l * 100) };
}

export function hslToRgb({ h, s, l }: HSL): RGB {
  const sn = s / 100, ln = l / 100;
  const c = (1 - Math.abs(2 * ln - 1)) * sn;
  const hp = (((h % 360) + 360) % 360) / 60;
  const x = c * (1 - Math.abs((hp % 2) - 1));
  let r = 0, g = 0, b = 0;
  if (hp >= 0 && hp < 1) [r, g, b] = [c, x, 0];
  else if (hp < 2) [r, g, b] = [x, c, 0];
  else if (hp < 3) [r, g, b] = [0, c, x];
  else if (hp < 4) [r, g, b] = [0, x, c];
  else if (hp < 5) [r, g, b] = [x, 0, c];
  else [r, g, b] = [c, 0, x];
  const m = ln - c / 2;
  return { r: round((r + m) * 255), g: round((g + m) * 255), b: round((b + m) * 255) };
}

export const hexToHsl = (hex: string): HSL | null => {
  const rgb = hexToRgb(hex);
  return rgb ? rgbToHsl(rgb) : null;
};
export const hslToHex = (hsl: HSL): string => rgbToHex(hslToRgb(hsl));

// =============================================================================
// parseColor — accept hex / rgb() / rgba() / hsl() / hsla() / named -> RGB
// =============================================================================
export function parseColor(input: string): RGB | null {
  const str = input.trim().toLowerCase();
  if (!str) return null;

  if (str.startsWith("#")) return hexToRgb(str);

  if (NAMED_COLORS[str]) return hexToRgb(NAMED_COLORS[str]);

  const fn = str.match(/^(rgba?|hsla?)\(([^)]+)\)$/);
  if (fn) {
    const kind = fn[1];
    // split on commas and/or slashes and/or whitespace
    const parts = fn[2].split(/[\s,/]+/).filter(Boolean);
    if (parts.length < 3) return null;

    const num = (p: string, max: number) => {
      if (p.endsWith("%")) return (parseFloat(p) / 100) * max;
      return parseFloat(p);
    };

    if (kind.startsWith("rgb")) {
      const r = num(parts[0], 255);
      const g = num(parts[1], 255);
      const b = num(parts[2], 255);
      if ([r, g, b].some(Number.isNaN)) return null;
      return { r: clamp(round(r), 0, 255), g: clamp(round(g), 0, 255), b: clamp(round(b), 0, 255) };
    } else {
      const h = parseFloat(parts[0]);
      const s = parseFloat(parts[1]); // expects %
      const l = parseFloat(parts[2]);
      if ([h, s, l].some(Number.isNaN)) return null;
      return hslToRgb({ h, s, l });
    }
  }
  return null;
}

// =============================================================================
// Contrast & readability (WCAG)
// =============================================================================
export function relativeLuminance({ r, g, b }: RGB): number {
  const ch = (c: number) => {
    const s = c / 255;
    return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4);
  };
  return 0.2126 * ch(r) + 0.7152 * ch(g) + 0.0722 * ch(b);
}

export function contrastRatio(a: RGB, b: RGB): number {
  const la = relativeLuminance(a);
  const lb = relativeLuminance(b);
  const [hi, lo] = la > lb ? [la, lb] : [lb, la];
  return (hi + 0.05) / (lo + 0.05);
}

/** Returns "#000000" or "#ffffff" — whichever is more readable on `bg`. */
export function readableText(bg: RGB): string {
  const white = { r: 255, g: 255, b: 255 };
  const black = { r: 0, g: 0, b: 0 };
  return contrastRatio(bg, white) >= contrastRatio(bg, black) ? "#ffffff" : "#000000";
}

export function readableTextHex(hex: string): string {
  const rgb = hexToRgb(hex);
  return rgb ? readableText(rgb) : "#000000";
}

export const wcagLabel = (ratio: number): string => {
  if (ratio >= 7) return "AAA";
  if (ratio >= 4.5) return "AA";
  if (ratio >= 3) return "AA Large";
  return "Fail";
};

// =============================================================================
// Harmony schemes — from a base hex, return an array of hex colors.
// =============================================================================
export type Scheme =
  | "complementary"
  | "analogous"
  | "triadic"
  | "tetradic"
  | "split-complementary"
  | "monochromatic"
  | "shades";

const rotate = (h: number, deg: number) => (((h + deg) % 360) + 360) % 360;

export function generateScheme(baseHex: string, scheme: Scheme, count = 5): string[] {
  const base = hexToHsl(baseHex);
  if (!base) return [baseHex];
  const { h, s, l } = base;

  const fromHues = (hues: number[]): string[] => {
    // Distribute `count` swatches across the anchor hues, varying lightness
    // gently so even a 5-swatch complementary scheme feels full.
    const out: string[] = [];
    const per = Math.max(1, Math.ceil(count / hues.length));
    for (const hue of hues) {
      for (let i = 0; i < per && out.length < count; i++) {
        const lift = per === 1 ? 0 : (i - (per - 1) / 2) * 14;
        out.push(hslToHex({ h: hue, s: clamp(s, 8, 100), l: clamp(l + lift, 8, 94) }));
      }
    }
    return out.slice(0, count);
  };

  switch (scheme) {
    case "complementary":
      return fromHues([h, rotate(h, 180)]);
    case "analogous":
      return fromHues([rotate(h, -60), rotate(h, -30), h, rotate(h, 30), rotate(h, 60)]);
    case "triadic":
      return fromHues([h, rotate(h, 120), rotate(h, 240)]);
    case "tetradic":
      return fromHues([h, rotate(h, 90), rotate(h, 180), rotate(h, 270)]);
    case "split-complementary":
      return fromHues([h, rotate(h, 150), rotate(h, 210)]);
    case "monochromatic": {
      const out: string[] = [];
      for (let i = 0; i < count; i++) {
        const t = count === 1 ? 0.5 : i / (count - 1);
        out.push(hslToHex({ h, s: clamp(s, 6, 100), l: clamp(18 + t * 70, 6, 96) }));
      }
      return out;
    }
    case "shades": {
      const out: string[] = [];
      for (let i = 0; i < count; i++) {
        const t = count === 1 ? 0.5 : i / (count - 1);
        out.push(hslToHex({ h, s, l: clamp(90 - t * 78, 6, 94) }));
      }
      return out;
    }
  }
}

// =============================================================================
// Tonal ramps in the shape semantica's tokens.css expects.
// =============================================================================

// Lightness/saturation targets per stop. Tuned to feel like Tailwind's slate
// (neutral) and blue (accent) ramps so generated themes look professional.
const NEUTRAL_STOPS: Array<[string, number, number]> = [
  // [stop, lightness, saturationScale(0..1 of base sat, floored)]
  ["50", 98, 0.6], ["100", 96, 0.7], ["200", 91, 0.8], ["300", 84, 0.9],
  ["400", 67, 1], ["500", 49, 1], ["600", 39, 1], ["700", 29, 1],
  ["800", 18, 1], ["900", 11, 1], ["950", 4, 1],
];

const ACCENT_STOPS: Array<[string, number]> = [
  ["300", 76], ["400", 67], ["500", 59], ["600", 51], ["700", 43],
];

export interface SemanticaTokens {
  gray: Record<string, string>;
  accent: Record<string, string>;
  success: string;
  warning: string;
  danger: string;
}

/**
 * Build a full semantica primitive palette from an accent color and an
 * optional neutral seed. The neutral ramp is subtly tinted toward the chosen
 * hue (or the accent hue) so the theme feels cohesive rather than dead-gray.
 */
export function buildSemanticaTokens(
  accentHex: string,
  neutralHex?: string,
): SemanticaTokens {
  const accent = hexToHsl(accentHex) ?? { h: 217, s: 91, l: 60 };
  const neutralSeed = neutralHex ? hexToHsl(neutralHex) : null;
  const neutralHue = neutralSeed ? neutralSeed.h : accent.h;
  // Keep neutrals neutral: a low, fixed-ish chroma tinted toward the hue.
  const neutralSat = neutralSeed ? clamp(neutralSeed.s, 4, 22) : 14;

  const gray: Record<string, string> = {};
  for (const [stop, l, satScale] of NEUTRAL_STOPS) {
    gray[stop] = hslToHex({ h: neutralHue, s: clamp(neutralSat * satScale, 3, 24), l });
  }

  const accentSat = clamp(accent.s, 45, 100);
  const accents: Record<string, string> = {};
  for (const [stop, l] of ACCENT_STOPS) {
    accents[stop] = hslToHex({ h: accent.h, s: accentSat, l });
  }

  // Status colors: anchor hues, lightness/saturation matched to the accent's
  // vibrancy so they sit together. Hues are fixed (green/amber/red) on purpose.
  const status = (hue: number) =>
    hslToHex({ h: hue, s: clamp(accentSat, 55, 85), l: 50 });

  return {
    gray,
    accent: accents,
    success: status(142),
    warning: hslToHex({ h: 38, s: 92, l: 50 }),
    danger: hslToHex({ h: 0, s: 75, l: 51 }),
  };
}

// =============================================================================
// Misc helpers
// =============================================================================

/** Distance in RGB space — cheap near-duplicate test for de-duping palettes. */
export function rgbDistance(a: RGB, b: RGB): number {
  return Math.sqrt((a.r - b.r) ** 2 + (a.g - b.g) ** 2 + (a.b - b.b) ** 2);
}

export function normalizeHex(input: string): string | null {
  const rgb = parseColor(input);
  return rgb ? rgbToHex(rgb) : null;
}

/** Random pleasant hex (good saturation/lightness range). */
export function randomHex(seed: number): string {
  // Deterministic-ish given a seed so callers control variation (no Math.random
  // needed). Golden-ratio hue stepping keeps successive hues well spread.
  const h = (seed * 137.508) % 360;
  const s = 55 + ((seed * 53) % 35);
  const l = 45 + ((seed * 29) % 20);
  return hslToHex({ h, s, l });
}

