// =============================================================================
// bookmarklet.ts — build a self-contained recolor script that the user runs on
// ANY real website (via a bookmarklet or pasted into the console). It runs in
// the target page's own context, so there is no proxy and nothing to break:
// it reads each element's *computed* colors and overrides them inline with the
// nearest palette hue (keeping the original lightness so the page stays
// readable), then keeps watching for dynamically-added content.
// =============================================================================
import { hexToHsl } from "./color";

export interface BookmarkletOptions {
  neutralsToo: boolean;
}

// The engine that runs inside the target page. `__P__` / `__N__` are replaced
// with the palette anchors and the "recolor neutrals" flag. Kept dependency-free
// and compact; computed colors are always rgb()/rgba(), so parsing is simple.
const ENGINE = `(function(){
  var P=__P__,N=__N__;
  if(!P.length){return;}
  var PROPS=['color','background-color','border-top-color','border-right-color','border-bottom-color','border-left-color','outline-color','text-decoration-color','caret-color','fill','stroke','column-rule-color'];
  function parse(v){
    if(!v)return null;
    var m=v.match(/rgba?\\(([^)]+)\\)/i);if(!m)return null;
    var p=m[1].split(/[ ,\\/]+/).filter(Boolean).map(parseFloat);
    if(p.length<3)return null;
    var a=p.length>3?p[3]:1;return {r:p[0],g:p[1],b:p[2],a:a};
  }
  function hsl(r,g,b){
    r/=255;g/=255;b/=255;var mx=Math.max(r,g,b),mn=Math.min(r,g,b),d=mx-mn,h=0,l=(mx+mn)/2;
    if(d){if(mx==r)h=((g-b)/d)%6;else if(mx==g)h=(b-r)/d+2;else h=(r-g)/d+4;h*=60;if(h<0)h+=360;}
    var s=d?d/(1-Math.abs(2*l-1)):0;return {h:h,s:s*100,l:l*100};
  }
  function nearest(h){var b=P[0],bd=999;for(var i=0;i<P.length;i++){var dd=Math.abs(P[i].h-h)%360;if(dd>180)dd=360-dd;if(dd<bd){bd=dd;b=P[i];}}return b;}
  function tint(c){var x=hsl(c.r,c.g,c.b);if(x.s<14&&!N)return null;var p=nearest(x.h);var s=Math.max(x.s<14?16:22,Math.min(p.s,92));return 'hsl('+Math.round(p.h)+','+Math.round(s)+'%,'+Math.round(x.l)+'%)';}
  function paint(el){
    if(el.nodeType!==1||el.dataset&&el.dataset.__rc)return;
    var cs=getComputedStyle(el);
    for(var i=0;i<PROPS.length;i++){
      var pr=PROPS[i],v=cs.getPropertyValue(pr),c=parse(v);
      if(!c||c.a===0)continue;
      var nv=tint(c);if(nv)el.style.setProperty(pr,nv,'important');
    }
    try{el.dataset.__rc='1';}catch(e){}
  }
  function run(root){
    paint(root);
    var els=root.querySelectorAll?root.querySelectorAll('*'):[];
    for(var i=0;i<els.length&&i<25000;i++)paint(els[i]);
  }
  run(document.documentElement);
  try{
    var mo=new MutationObserver(function(ms){for(var i=0;i<ms.length;i++){var an=ms[i].addedNodes;for(var j=0;j<an.length;j++)if(an[j].nodeType===1)run(an[j]);}});
    mo.observe(document.documentElement,{childList:true,subtree:true});
    window.__rcStop=function(){mo.disconnect();};
  }catch(e){}
})();`;

function anchors(paletteHexes: string[]): { h: number; s: number }[] {
  const hsls = paletteHexes
    .map((h) => hexToHsl(h))
    .filter((x): x is NonNullable<typeof x> => !!x)
    .map((x) => ({ h: x.h, s: x.s }));
  const chromatic = hsls.filter((x) => x.s >= 12);
  return chromatic.length ? chromatic : hsls;
}

/** Readable script you can paste into the DevTools console. */
export function buildSnippet(paletteHexes: string[], opts: BookmarkletOptions): string {
  return ENGINE.replace("__P__", JSON.stringify(anchors(paletteHexes))).replace(
    "__N__",
    String(opts.neutralsToo),
  );
}

/** The `javascript:` URL for a draggable bookmarklet. */
export function buildBookmarklet(paletteHexes: string[], opts: BookmarkletOptions): string {
  return "javascript:" + encodeURIComponent(buildSnippet(paletteHexes, opts));
}

