// =============================================================================
// export.ts — turn palettes / token sets into copy-paste-ready code.
// =============================================================================
import { SemanticaTokens, readableTextHex } from "./color";

export interface Swatch {
  hex: string;
  name?: string;
}

export function toCssVars(swatches: Swatch[], prefix = "color"): string {
  const lines = swatches.map((s, i) => `  --${prefix}-${i + 1}: ${s.hex};`);
  return `:root {\n${lines.join("\n")}\n}`;
}

export function toScss(swatches: Swatch[], prefix = "color"): string {
  return swatches.map((s, i) => `$${prefix}-${i + 1}: ${s.hex};`).join("\n");
}

export function toJson(swatches: Swatch[]): string {
  return JSON.stringify(
    swatches.map((s, i) => ({ name: s.name ?? `color-${i + 1}`, hex: s.hex })),
    null,
    2,
  );
}

export function toTailwind(swatches: Swatch[], key = "brand"): string {
  const entries = swatches
    .map((s, i) => `        "${(i + 1) * 100}": "${s.hex}",`)
    .join("\n");
  return [
    "// tailwind.config.js",
    "module.exports = {",
    "  theme: { extend: { colors: {",
    `    ${key}: {`,
    entries,
    "    },",
    "  } } },",
    "};",
  ].join("\n");
}

export function toSvg(swatches: Swatch[]): string {
  const w = 120, h = 160;
  const total = swatches.length * w;
  const rects = swatches
    .map((s, i) => {
      const x = i * w;
      const text = readableTextHex(s.hex);
      return (
        `  <rect x="${x}" y="0" width="${w}" height="${h}" fill="${s.hex}"/>\n` +
        `  <text x="${x + w / 2}" y="${h - 16}" fill="${text}" font-family="monospace" ` +
        `font-size="13" text-anchor="middle">${s.hex}</text>`
      );
    })
    .join("\n");
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${total}" height="${h}" viewBox="0 0 ${total} ${h}">\n${rects}\n</svg>`;
}

/**
 * Compact override of just the raw color primitives. Because semantica's
 * semantic tokens (and its dark theme) reference these via var(), overriding
 * them retemes the whole library in both light and dark.
 */
export function toSemanticaOverride(t: SemanticaTokens): string {
  const grayLines = Object.entries(t.gray)
    .map(([k, v]) => `  --sui-gray-${k}: ${v};`)
    .join("\n");
  const accentLines = Object.entries(t.accent)
    .map(([k, v]) => `  --sui-accent-${k}: ${v};`)
    .join("\n");
  return [
    "/* Generated by Palette Studio — import AFTER semantica to retheme it. */",
    ":root {",
    "  /* neutral ramp */",
    grayLines,
    "",
    "  /* accent ramp */",
    accentLines,
    "",
    "  /* status */",
    `  --sui-green-500: ${t.success};`,
    `  --sui-amber-500: ${t.warning};`,
    `  --sui-red-500:   ${t.danger};`,
    `  --sui-red-600:   ${t.danger};`,
    "}",
  ].join("\n");
}

