87	  }, []);
88	  const copy = useCallback(async (text: string, k: string) => {
89	    try { await navigator.clipboard.writeText(text); flash(k); } catch { /* blocked */ }
90	  }, [flash]);
91	
92	  const regenerate = useCallback((base: string, sc: Scheme, n: number) => {
93	    const gen = generateScheme(base, sc, n);
94	    setPalette((prev) => {
95	      const out: Sw[] = [];
96	      for (let i = 0; i < n; i++) out.push(prev[i]?.locked ? prev[i] : { hex: gen[i] ?? base, locked: false });
97	      return out;
98	    });
99	  }, []);
100	  const applyAccent = useCallback((hex: string) => {
101	    const norm = normalizeHex(hex);
102	    if (!norm) return;
103	    setAccent(norm);
104	    regenerate(norm, scheme, count);
